import React, { useRef, useState } from "react"
import TelefonoArgentino from '../js/telefonos_argentinos'
import ReCAPTCHA from 'react-google-recaptcha'

const QuoteBlock = ({ classCss }) => {
  const [dataForm, setDataForm] = useState({})
  const [feedback, setFeedback] = useState({})
  const [result, setResult] = useState()
  const recaptcha = useRef()

  const restForm = () => {
    Object.keys(dataForm).forEach(step => {
      dataForm[step] = ''
    })
  }

  const handleChange = event => {
    setResult("")
    setDataForm({ ...dataForm, [event.target.id]: event.target.value })

    if (event.target.value === "") {
      setFeedback({
        ...feedback, [event.target.id]: (<div className="invalid-feedback d-block ">
          El campo no puede estar vacío
        </div>
        )
      })
    }
    else if (event.target.id === 'phone') {
      var tel = new TelefonoArgentino(event.target.value);
      if (tel.isValid() === false) {
        setFeedback({
          ...feedback, [event.target.id]: (<div className="invalid-feedback d-block ">
            El teléfono no es válido
          </div>
          )
        })
      } else {
        setFeedback({ ...feedback, [event.target.id]: "" })
      }
    } else {
      setFeedback({ ...feedback, [event.target.id]: "" })
    }

  }

  const fieldIsEmpty = (step) => {
    setFeedback({
      ...feedback, [step]: (<div className="invalid-feedback d-block ">
        El campo no puede estar vacío
      </div>
      )
    })
  }

  const handleSubmit = event => {
    event.preventDefault()

    const captchaValue = recaptcha.current.getValue()
    if (!captchaValue) {
      setResult((<div className="alert alert-warning" role="alert">Verificar el campo reCAPTCHA.</div>))
      return false
    } else {
      setResult("")
    }

    let count = 0
    for (const step of ['phone', 'email', 'msg', 'name']) {
      if (Object.keys(dataForm).length === 0) {
        count++;
        fieldIsEmpty(step)
        continue
      }
      if (!dataForm.hasOwnProperty(step)) {
        count++;
        fieldIsEmpty(step)
        continue
      }
      if (dataForm[step] === "") {
        count++;
        fieldIsEmpty(step)
      }

      if (feedback[step] !== "") {
        count++;
      }
    }

    if (count > 0) {
      return false
    }

    setResult((<div class="d-flex align-items-center">
      <strong>Enviando formulario...</strong>
      <div class="spinner-border ml-auto" role="status" aria-hidden="true"></div>
    </div>))

    const scriptURL =
      "https://script.google.com/macros/s/AKfycbzfhVIHoIHqvyor8DlDtlEAoHAuUggah3gAYwMz8gMaK8j6b8e6vMVt65F1_VjfNGi7/exec"

    const formData = new FormData()
    Object.keys(dataForm).forEach(step => {
      formData.append(step, dataForm[step])
    })

    fetch(scriptURL, {
      redirect: "follow",
      method: "POST",
      body: formData
    })
      .then(() => {
        // console.log("Success!")
        setResult((<div className="alert alert-success" role="alert">El formulario se ha enviado correctamente, nos pondremos en contacto con usted en breve.</div>))
        restForm()
      })
      .catch(error => {
        console.error("Error!", error.message)
        setResult((<div className="alert alert-danger" role="alert">Se ha producido un problema al enviar el formulario, póngase en contacto con nosotros por correo electrónico info@electrotecniaml.com.ar</div>))
      })
  }

  return (
    <div className={classCss}>
      <form method="POST" onSubmit={handleSubmit}>
        <div className="row">
          <div className="col-md-6">
            <p>
              <label htmlFor="name">Nombre / Razón Social</label>
              <input
                type="text"
                onChange={handleChange}
                value={dataForm['name']}
                id="name"
                name="name"
                placeholder="Nombre / Razón Social..."
              />

            </p>
            {feedback['name']}
          </div>
          <div className="col-md-6">
            <p>
              <label htmlFor="email">Email</label>
              <input
                type="email"
                onChange={handleChange}
                value={dataForm['email']}
                id="email"
                name="email"
                placeholder="Email..."
              />
            </p>
            {feedback['email']}
          </div>
        </div>
        <div className="row">
          <div className="col-md-6">
            <p>
              <label htmlFor="phone">Teléfono</label>
              <input
                type="text"
                onChange={handleChange}
                value={dataForm['phone']}
                id="phone"
                name="phone"
                placeholder="Teléfono..."
              />
            </p>
            {feedback['phone']}
          </div>
        </div>
        <div className="row">
          <div className="col-md-12">
            <p>
              <label htmlFor="msg">¿Cómo podemos ayudarte?</label>
              <textarea
                id="msg"
                onChange={handleChange}
                value={dataForm['msg']}
                name="msg"
                placeholder="Mensaje..."
              ></textarea>
            </p>
            {feedback['msg']}
          </div>
        </div>

        <ReCAPTCHA ref={recaptcha} hl={'es-419'} sitekey={'6LegV0MqAAAAAGroKfJ-pbO07vnUGr2l9mPnWjn1'} />

        <div className="row">
          <div className="col-md-12">
            <p>
              <button type="submit">solicitar presupuesto</button>
            </p>
          </div>
        </div>
      </form>

      {result}

    </div>
  )
}

export default QuoteBlock
